arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"types":"public_channel,private_channel","exclude_archived":true,"limit":1000}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d.get('error'), d.get('response_metadata')); sys.exit()
for c in d['channels']:
    name=c.get('name','')
    if 'incident' in name.lower():
        print(json.dumps({'id':c['id'],'name':name,'is_private':c.get('is_private'),'topic':(c.get('topic') or {}).get('text',''),'purpose':(c.get('purpose') or {}).get('text','')}, ensure_ascii=False))
"

