arguments.command:
curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"limit":0}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d.get('error'), d.get('response_metadata')); sys.exit()
for u in d['members']:
    if 'aisha' in u.get('real_name','').lower() or 'aisha' in u.get('profile',{}).get('display_name','').lower():
        print(json.dumps({'id':u['id'],'real_name':u.get('real_name'),'display_name':u.get('profile',{}).get('display_name',''),'deleted':u.get('deleted',False)}, ensure_ascii=False))
"

